import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    iterator = iter(lines)
    try:
        n, m = map(int, next(iterator).split())
    except StopIteration:
        return ''

    offers = []
    for _ in range(m):
        l, r = map(int, next(iterator).split())
        offers.append((l, r))

    # results[x] will store total occupied days for x = 1, 2, ..., n
    results = [0] * (n + 1)

    # For efficient interval occupation tracking, we use a segment tree
    # Each node stores whether all positions in its range are marked as occupied
    class SegmentTree:
        def __init__(self, n):
            self.size = 1
            while self.size <= n:
                self.size *= 2
            self.n = n
            # Each node stores either occ (true if range is fully occupied) or min(0/1)
            # We use 1 to mark completely occupied, 0 otherwise
            self.tree = [0] * (4 * n)

        def query_occupied(self, node, start, end, l, r):
            # Check if range [l, r] overlaps with any marked position
            if l > end or r < start:
                return False  # No overlap
            if l <= start and end <= r:
                return self.tree[node] > 0  # If marked as occupied, return True

            mid = (start + end) // 2
            left_overlap = self.query_occupied(2 * node, start, mid, l, r)
            right_overlap = self.query_occupied(2 * node + 1, mid + 1, end, l, r)

            return left_overlap or right_overlap

        def update_occupied(self, node, start, end, l, r, u_type):
            # u_type: 0 if fully occupied, 1 if partially
            if l > end or r < start:
                # Not overlapping at all
                return
            if l <= start and end <= r:
                if u_type == 0:
                    self.tree[node] = 1  # Fully occupied
                self.tree = [max(self.tree[idx], 1)] if 2*node < len(self.tree) else self.tree
                return 1  # Marked as fully occupied
            mid = (start + end) // 2
            left_val = self.update_occupied(2 * node, start, mid, l, r, u_type)
            right_val = self.update_occupied(2 * node + 1, mid + 1, end, l, r, u_type)
            # Propagate
            new_val = max(left_val, right_val)
            if new_val == 1:
                self.tree[node] = 1
            return new_val

    # For each x from 1 to n, process offers
    for x in range(1, n + 1):
        current_occupied = [False] * (n + 2)  # 1-indexed, with sentinel
        total_days = 0

        for l, r in offers:
            # Check length constraint
            if r - l + 1 < x:
                continue

            # Check if any day in [l, r] is already occupied
            conflict = False
            for d in range(l, r + 1):
                if current_occupied[d]:
                    conflict = True
                    break
            if conflict:
                continue

            # Accept the offer
            for d in range(l, r + 1):
                current_occupied[d] = True
            total_days += (r - l + 1)

        results[x] = total_days

    return '\n'.join(str(results[x]) for x in range(1, n + 1))

def solution(input_str):
    MOD = 1000000007

    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    # Identify which values are present in the array
    present = set()
    for x in arr:
        if x != -1:
            present.add(x)

    # Find all missing values (values that need to be placed in -1 positions)
    missing = []
    for i in range(1, n + 1):
        if i not in present:
            missing.append(i)

    m = len(missing)  # number of empty positions

    # Count k: positions i where arr[i] == -1 AND value (i+1) is in missing set
    # These are potential fixed points we don't want to create
    k = 0
    for i in range(n):
        if arr[i] == -1:
            val = i + 1  # The value that would be at position i+1 (1-indexed)
            if val in missing:
                k += 1

    # Precompute factorials for efficient computation
    fact = [1] * (m + 1)
    for i in range(1, m + 1):
        fact[i] = fact[i - 1] * i % MOD

    # Precompute inverse factorials for combinations
    inv = [1] * (m + 1)
    inv[m] = pow(fact[m], MOD - 2, MOD)
    for i in range(m - 1, -1, -1):
        inv[i] = inv[i + 1] * (i + 1) % MOD

    # nCr function using precomputed factorials
    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv[r] % MOD * inv[n - r] % MOD

    # Apply inclusion-exclusion principle
    # Sum over j: (-1)^j * C(k, j) * (m - j)!
    ans = 0
    for j in range(k + 1):
        term = nCr(k, j) * fact[m - j] % MOD
        if j % 2 == 0:
            ans = (ans + term) % MOD
        else:
            ans = (ans - term) % MOD

    return str(ans % MOD)

