def welzl(points, n, R=[], on_bor=True):
    """Welzl's algorithm for minimum enclosing sphere"""
    if n == 0 or len(R) == 4:
        # Base cases: compute sphere from boundary points
        if len(R) == 1:
            return [(R[0][0], R[0][0]), R[0][0][2]], 0
        elif len(R) == 2:
            return sphere_from_two(R[0], R[1])
        elif len(R) == 3:
            return sphere_from_three(R[0], R[1], R[2])
        elif len(R) == 4:
            return sphere_from_four(R[0], R[1], R[2], R[3])
        else:
            return [(0.0, 0.0, 0.0)], 0.0

    # Pick a random point and recurse
    pivot = points[n - random.randint(0, n - 1)]
    sphere_rest, radius = welzl(points, n - 1, R, on_bor)

    # If pivot is inside or on boundary of current sphere, return it
    if radius == 0 or dist(pivot, sphere_rest) <= radius + 1e-9:
        return sphere_rest, radius

    # Otherwise, add pivot to boundary and recurse
    sphere_new, radius = welzl(points, n - 1, R + [pivot], False)
    return sphere_new, radius

