                            if dp[i-1][j-1][prev_k] + 1 > dp[i][j][new_k]:
                                dp[i][j][new_k] = dp[i-1][j-1][prev_k] + 1
                                parent[i][j][new_k] = (s1[i-1], i-1, j-1, prev_k)

    # Find the maximum result
    max_len = 0
    best_k = 0
