    parent = [0] * (n + 1)

    def dfs_find_cycle():
        stack = [1]
        visited[1] = True

        while stack:
            u = stack[-1]

            neighbors = adj[u]
            idx = 0
            for i in range(len(neighbors)):
                if neighbors[i] in visited:
                    idx = i
                    break

            if idx < len(neighbors):
                v = neighbors[idx]
                if v == parent[u]:
                    idx += 1
                else:
                    # Pruning: avoid reprocessing visited neighbors
                    continue

            if all(u):
                stack.pop()
                visited[u] = False
                return

            found_cycle = False

            for v in adj[u]:
                if v == parent[u]:
