def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    strengths = list(map(int, lines[1].split()))
    m = int(lines[2])
    actions = []
    for i in range(m):
        parts = lines[3 + i].split()
        actions.append((parts[0], int(parts[1])))

    # Sort strengths and consider only top m heroes
    strengths.sort(reverse=True)
    top_m = strengths[:m]

    # Memoization: state is (action_idx, bitmask of available heroes)
    memo = {}

    def solve(idx, mask):
        """
        Returns the optimal (score1 - score2) from this state onward.
        """
        state = (idx, mask)
        if state in memo:
            return memo[state]

        if idx == m:
            return 0

        action, team = actions[idx]

        # Get highest-ranked available hero
        best = None
        highest_bit = -1  # index of highest strength available

        # First, check if we're at base case
        if mask == 0:
            memo[state] = 0
            return 0

        # Find which heroes are available
        for i in range(len(top_m)):
            if mask & (1 << i):
                # Track the highest strength available
                pass

        # Try each available hero
        for i in range(len(top_m)):
            if mask & (1 << i):
                new_mask = mask ^ (1 << i)

                if action == 'p':
                    # Pick: chosen hero joins the team's score
                    if team == 1:
                        # Team 1 maximizes (score1 - score2)
                        val = top_m[i] + solve(idx + 1, new_mask)
                    else:
                        # Team 2 minimizes (score1 - score2)
                        val = solve(idx + 1, new_mask) - top_m[i]
                else:
                    # Ban: hero removed without adding to any score
                    if team == 1:
                        # Team 1 maximizes (score1 - score2)
                        val = solve(idx + 1, new_mask)
                    else:
                        # Team 2 minimizes (score1 - score2)
                        val = solve(idx + 1, new_mask)

                # Choose optimally based on team
                if best is None:
                    best = val
                else:
                    if team == 1:
                        best = max(best, val)
                    else:
                        best = min(best, val)

        memo[state] = best
        return best

    # All heroes initially available (bits 0 to m-1 set)
    initial_mask = (1 << m) - 1
    result = solve(0, initial_mask)

    return str(result) + '\n'

