MOD = 10**9 + 7

def compute_len_pow(length, n):
    """Compute 10^length mod MOD"""
    length %= (MOD - 1)  # Fermat's Little Theorem
    return pow(10, length, MOD)

def compute_prefix_n(len_list):
    """Compute prefix sums of lengths"""
    result = 0
    for l in len_list:
        result = (result + l) % (MOD - 1)
        yield result

def compute_concat_values(values, lengths):
    """Compute concatenated values from right to left"""
    if not values:
        return 0
    n = len(values)
    result = 0
    length_so_far = 0
    for i in range(n-1, -1, -1):
        shift = pow(10, length_so_far, MOD)
        result = (values[i] * shift + result) % MOD
        length_so_far += lengths[i]
    return result

def multiply_by_power(base, length):
    """Multiply by 10^length"""
    length %= (MOD - 1)
    return (base * pow(10, length, MOD)) % MOD

def parse_number(s, pos):
    """Parse a number starting at position pos, return (value, new_pos)"""
    j = pos
    val = 0
    while j < len(s) and s[j].isdigit():
        if s[j] == '0' and j == pos:
            break
        val = val * 10 + int(s[j])
        j += 1
    return val, j

class Evaluator:
    def __init__(self, s):
        self.s = s
        self.pos = 0

    def skip_parens_and_get(self):
        """Try to skip matching parentheses and return character at outer"""
        if self.pos >= len(self.s):
            return None
        if self.s[self.pos] == '(' or self.s[self.pos] == ')':
            return self.s[self.pos]
        return self.s[self.pos]

    def find_matching_close(self, open_pos):
        """Find matching closing parenthesis"""
        depth = 1
        i = open_pos + 1
        while i < len(self.s) and depth > 0:
            if self.s[i] == '(':
                depth += 1
            elif self.s[i] == ')':
                depth -= 1
            i += 1
        return i - 1

    def parse_term(self):
        """Parse a single term: number, or number-range, or repeated expression"""
        l_val, l_pos = parse_number(self.s, self.pos)
        self.pos = l_pos

        if self.pos >= len(self.s):
            return {'value': l_val, 'length': len(str(l_val))}

        if self.s[self.pos] == '-':
            self.pos += 1  # consume '-'
            r_val, r_pos = parse_number(self.s, self.pos)
            self.pos = r_pos

            # Compute concatenation of numbers from l_val to r_val
            total_length = 0
            values = []
            len_list = []

            for num in range(l_val, r_val + 1):
                s_num = str(num)
                values.append(num)
                length = len(s_num)
                len_list.append(length)
                total_length = (total_length + length) % (MOD - 1)

            return {'value': compute_concat_values(values, len_list), 
                    'length': total_length}

        elif self.s[self.pos] == '(':
            n_val, n_pos = parse_number(self.s, self.pos)
            self.pos = n_pos
            self.pos += 1  # consume '('

            # Find the matching closing parenthesis
            expr_start = self.pos

            # Parse expression by scanning
            expr_end = self.find_matching_close(expr_start - 1) + 1

            expr_eval = self.Evaluator(self.s[expr_start:expr_end]).parse_expression()

            self.pos = expr_end
            # Consume ')'
            while self.pos < len(self.s) and self.s[self.pos] == ')':
                self.pos += 1

            # Compute repetition
            values = []
            lengths = []
            for _ in range(n_val):
                values.append(expr_eval['value'])
                lengths.append(expr_eval['length'])

            n_len = expr_eval['length']
            if n_val > 0:
                total_length = (n_len * n_val) % (MOD - 1)
            else:
                total_length = 0

            return {'value': compute_concat_values(values, lengths),
                    'length': total_length}
        else:
            return {'value': l_val, 'length': len(str(l_val))}

    def parse_expression(self):
        """Parse full expression: sum of terms separated by +"""
        if self.pos >= len(self.s):
            return {'value': 0, 'length': 0}

        term1 = self.parse_term()
        if term1['length'] == 0 and term1['value'] == 0:
            return term1

        result = term1
        while self.pos < len(self.s) and self.s[self.pos] == '+':
            self.pos += 1
            term2 = self.parse_term()
            if term2['value'] > 0:
                result = concatenate(result, term2)

        return result

def concatenate(a, b):
    """Concatenate value a and value b"""
    if a['length'] == 0:
        return {'value': b['value'], 'length': b['length']}
    if b['length'] == 0:
        return {'value': a['value'], 'length': a['length']}

    shift = pow(10, b['length'], MOD)
    new_value = (a['value'] * shift + b['value']) % MOD
    new_length = (a['length'] + b['length']) % (MOD - 1)

    return {'value': new_value, 'length': new_length}

