        edge_i = -1
        for i in range(m):
            if not used_edge[i]:
                edge_i = i
                break

        if edge_i == -1:
            return True  # All edges used

        u, v = edges[edge_i]

        # Find all available adjacent edges (sharing u or v)
        candidates = []
        for neighbor, idx in adj[u]:
