                if visited[v] == 0 or visited[v] == 1:
                    cycle_gcd[u] = gcd(cycle_gcd[u], dist[u] + w - dist[v])

    if stack:
        while stack:
            u = stack.pop()
            in_stack[u] = False
            visited[u] = 2
            cycle_gcd[start] = gcd(cycle_gcd[start], cycle_gcd[u])
    else:
        if stack:
            while stack:
                u = stack.pop()
                in_stack[u] = False
                visited[u] = 2
                if dist[u] == 0:
                    cycle_gcd[start] = gcd(cycle_gcd[start], 0)

    for i in range(1, n + 1):
        if visited[i]:
            start = i
            while i in stack:
                i = stack.pop()
            visited[i] = 2
            in_stack[i] = False
            cycle_gcd[start] = 0
            for v, w in graph[start]:
                if visited[v] == 2:
                    cycle_gcd[start] = gcd(cycle_gcd[start], dist[start] + w - dist[v])

        if visited[start] and graph[start]:
            for v, w in graph[start]:
                if visited[v] == 2:
                    cycle_gcd[start] = gcd(cycle_gcd[start], dist[start] + w - dist[v])

    for start in range(1, n + 1):
        if visited[start] != 2:
            visited[start] = 2
            in_stack[start] = False
            while stack and stack[-1] == start:
                stack.pop()
            in_stack[start] = False

    results = []
    for _ in range(q):
        v_i, s_i, t_i = map(int, lines[idx].split())
        idx += 1

        if s_i == 0:
            results.append("YES")
        else:
            if cycle_gcd[v_i] == 0:
                results.append("NO")
            else:
                if (t_i - s_i) % cycle_gcd[v_i] == 0:
                    results.append("YES")
                else:
                    results.append("NO")

    return '\n'.join(results)

