    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    stack = []  # Each element: (average, count, length)

    for x in a:
        stack.append((float(x), 1, 1))

        while stack and stack[-1][0] >= x:
            avg, count, _ = stack.pop()
            stack.append((avg, count + 1, count + 1))

    result = []
    for avg, count, _ in stack:
        result.append([avg] * count)

