import sys
from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    tests = []
    for i in range(1, t + 1):
        line = lines[i].strip()
        if line:
            tests.append(int(line))

    # Precompute Fibonacci numbers up to 10^18
    # F1 = 1, F2 = 2, Fi = Fi-1 + Fi-2
    fib = [1, 2]
    while True:
        nxt = fib[-1] + fib[-2]
        if nxt > 10**18:
            break
        fib.append(nxt)

    def count_ways(n):
        @lru_cache(maxsize=None)
        def dp(idx, remaining):
            """Count ways to form 'remaining' using distinct Fibonacci numbers
            from fib[idx] and below."""
            if remaining == 0:
                return 1

            if idx < 0:
                return 0

            # Option 1: Skip fib[idx]
            res = dp(idx - 1, remaining)

            # Option 2: Use fib[idx] (if it doesn't exceed remaining)
            if remaining >= fib[idx]:
                # Using fib[idx] means it's unavailable for this decomposition
                # But we just need to ensure distinctness which is handled by
                # not revisiting the same index
                res += dp(idx - 1, remaining - fib[idx])

            return res

        # Start from the largest Fibonacci number <= n
        idx = len(fib) - 1 if fib[-1] <= n else next(i for i, f in enumerate(fib) if f > n) - 1

        dp.cache_clear()
        return dp(idx, n)

    results = []
    for n in tests:
        results.append(str(count_ways(n)))

    return '\n'.join(results)

